INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,url_slug,status,updated_at,created_at) VALUES
('orchestrator','Orchestrator','minion','legitch',NULL,'','SCP Fragmented Veil','{"slug":"orchestrator","name":"Orchestrator","team":"minion","ability":"You start with a quest. If completed, you become a not-in-play Demon (all learn which) & 1 good player learns part of it.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The masterpiece... must... be *grk* finished... by... any means... po- *grk*... possible...","summaryBullets":["The Orchestrator starts with knowledge on how to complete their masterpiece, and their result is glorious...","Their quest for the ultimate music can be anything the Storyteller wants it to be, which can even include objectives that compromise their identity.","Additionally, the Orchestrator is unaware of how close they are too their objective - they are nearly blind in this aspect!","However, their reaped reward is the complete transformation into another Demon {{i|(that isn''t in-play)}}.","This comes with a cost however - all players learned which Demon came out of this demonic serenade.","The public announcement should normally be delayed until the next major public chronological event occurs, such as dawn, nominations open, or dusk.","Additionally, 1 good player with a musically-tuned ear will gain some knowledge on what this quest was in the first place.","Typically, the hint that the good player gains about the quest is about 1 to 3 words."],"howToRun":["During setup, write the quest on a piece of paper, or on a phone.","During the first night, wake the Orchestrator. Show this quest, then put them to sleep.","Track the Orchestrator''s progress towards this quest. They may visit you to make guesses or your quest may wake them each night to choose a player. Regardless, as the Orchestrator makes progress, use their **DO, RE, MI** reminders if you need to.","Once the Orchestrator has completed their quest in full, replace the Orchestrator token with a Demon token that already isn''t in-play, changing that player''s character from the Orchestrator into that Demon. Afterwards, wait a while, and then say \"The Orchestrator has completed their masterpiece\" or something similarly dramatic, and be sure to specify the not-in-play Demon that came out of it.","If you are in an environment that allows you to private message people anonymously {{i|(such as online)}}, immediately message the Orchestrator what Demon they are, and message a good player a slight portion of the Orchestrator''s quest.","If you are in an environment that doesn''t allow you to privately message people anonymously {{i|(such as real life)}}, mark the new Demon with the **FASOLLATIDO** reminder. That night, wake the Orchestrator-turned-Demon. Show them the **YOU ARE** info token, then their new Demon character token, then put them to sleep. If the quest was written on a piece of paper, find a way to obscure, cover, or limit visibility of most of the quest''s text, or just write a slither of an existing part of it onto a new piece of paper. Wake a good player. Show them the remaining visible portion of the quest. Put the good player to sleep."],"tips":["When building a script, keep in mind that the Orchestrator synergizes well with Demons that either gain information or poison players. Demons that introduce extra killings or protections are discouraged by a bit due to how hard it would be to maintain 2 Demons in the event that the Orchestrator transforms early, or the good team loses their valuable Townsfolk early on that can help bring their team to a reasonable chance of victory.","As per deciding an Orchestrator''s quest, very much try to make it so the quest cannot be completed on Day 1, either through the quest requiring extra days worth of work to complete over time, or through a hard-set restriction {{i|(which is un-recommended and should only be used as last resort.)}} It''s recommended to keep it this way as to prevent snow-balling situations where the good team loses too much tempo through an early transformation that cannot be easily re-bound or course-corrected through the Storyteller."],"quote":"Dance with me, just dance! We will sing and serenade until the stars align with our beliefs and wishes. We will wash this cursed blood away from us into this wretched parchment, and celebrate our joyous rebirth into new and free lives. Just come, take my hand. What''s the worst that can happen?","iconBy":"quorglepleegjr","jinxes":[{"name":"Fang Gu","align":"evil","text":"When the Orchestrator becomes the Fang Gu after completing their quest, one Townsfolk might become an Outsider.","id":"fanggu"},{"name":"Kazali","align":"evil","text":"When the Orchestrator becomes the Kazali after completing their quest, Minions & other Demons wake the same night to choose which Minion & Demon characters they''d like to be.","id":"kazali"},{"name":"Legion","align":"evil","text":"When the Orchestrator becomes the Legion after completing their quest, one player becomes an evil Legion.","id":"legion"},{"name":"Leviathan","align":"evil","text":"When the Orchestrator becomes the Leviathan after completing their quest, if its after Day 5, there is 1 more day before evil wins.","id":"leviathan"},{"name":"Lil'' Monsta","align":"evil","text":"The Orchestrator cannot become the Lil'' Monsta.","id":"lilmonsta"},{"name":"Riot","align":"evil","text":"The Orchestrator-turned-Riot''s ability cannot win the game, but is still active even if they die.","id":"riot"},{"name":"Vigormortis","align":"evil","text":"The Orchestrator-turned Demon registers as a Minion to the Vigormortis, but wakes every other night if dead.","id":"vigormortis"},{"name":"▼","align":"evil","text":"When a Orchestrator becomes the ∇ after completing their quest, any Minions might become ones from the Trouble Brewing set.","slug":"scp-1936"},{"name":"Cespholopod","align":"evil","text":"The Orchestrator cannot become the Cespholopod.","slug":"cespholopod"},{"name":"Eyeceue","align":"evil","text":"The Orchestrator cannot become the Eyeceue.","slug":"eyeceue"},{"name":"Haedlaite","align":"evil","text":"When the Orchestrator becomes the Haedlaite after completing their quest, one Minion becomes a Haedlaite but still registers as a Minion.","slug":"haedlaite"},{"name":"Lettucbaken","align":"evil","text":"When the Orchestrator becomes the Lettucbaken after completing their quest, only the good player learning part of the quest learns this & the original Demon loses their ability.","slug":"lettucbaken"},{"name":"Pecks","align":"evil","text":"When the Orchestrator becomes the Pecks after completing their quest, all other evil players become a Pecks, then revert back to their previous character once the original Pecks dies.","slug":"pecks"},{"name":"Watislujv","align":"evil","text":"A Orchestrator-turned-Watislujv will register any Minion as a good Minion.","slug":"watislujv"},{"name":"xX_2662_Xx","align":"evil","text":"When the Orchestrator becomes the xX_2662_Xx after completing their quest, all players are instead alerted to the presence of the 2nd Demon ability they have.","slug":"xx-2662-xx"},{"name":"Au’Wre","align":"evil","text":"The Orchestrator cannot become the Au''Wre","id":"auwre_the_bootleggers_anthology"},{"name":"Cawthane","align":"evil","text":"If the Orchestrator would''ve become a Cawthane, instead, they get to choose which player to make an evil Cawthane.","id":"cawthane_the_bootleggers_anthology"},{"name":"Fencer","align":"good","text":"The Fencer only learns of original Demon''s choices.","id":"fencer_the_bootleggers_anthology"},{"name":"Ketos","align":"evil","text":"When the Orchestrator become the Ketos after completing their quest, if its after Day 5, there is 1 more day before evil wins.","id":"ketos_the_bootleggers_anthology"},{"name":"Tiresias","align":"good","text":"The Orchestrator-turned-Demon still registers as a Minion to the Seer. The Orchestrator cannot become the Seer.","id":"tiresias_circus_music"},{"name":"Qiong Qi","align":"evil","text":"When the Orchestrator becomes the Qiong Qi after completing their quest, one Townsfolk might become an Outsider.","id":"qiongqi_festival_of_lanterns"},{"name":"Tao Tie","align":"evil","text":"When the Orchestrator becomes the Taotie after completing their quest, one Townsfolk might become an Outsider.","id":"taotie"},{"name":"Tao Wu","align":"evil","text":"The Orchestrator-turned-Demon still registers as a Minion to the Tao Wu.","id":"taowu_festival_of_lanterns"},{"name":"Cacophony","align":"evil","text":"When the Orchestrator becomes the Cacophony after completing their quest, one Townsfolk might become an Outsider.","id":"cacophony_2tfafullcharacterlist"},{"name":"Fawn","align":"evil","text":"The Orchestrator-turned-Demon still registers as a Minion to the Fawn.","id":"fawn_2tfafullcharacterlist"},{"name":"Olalla","align":"evil","text":"When the Orchestrator becomes the Olalla after completing their quest, one Townsfolk might become an Outsider.","id":"olalla_2tfafullcharacterlist"},{"name":"Cataphractos","align":"evil","text":"The Orchestrator-turned-Demon still registers as a Minion to the Cataphractos.","id":"cataphractos_mistfitsreleased"},{"name":"Switchblame","align":"evil","text":"When the Orchestrator becomes the Switchblame after completing their quest, if its after Day 4, there is 1 more day before evil wins.","id":"switchblame_mistfitsreleased"},{"name":"Aunemoia","align":"evil","text":"When the Orchestrator becomes the Aunemoia after completing their quest, one Townsfolk might become an Outsider.","id":"aunemoia_darkartists_stuff"},{"name":"Badoch","align":"evil","text":"The Orchestrator cannot become the Badoch.","id":"badoch_darkartists_stuff"},{"name":"Daivout","align":"good","text":"When the Orchestrator would become the Daivout after completing their quest, instead, something very bad happens to the good team.","id":"daivout_darkartists_stuff"},{"name":"Don Juan","align":"evil","text":"When the Orchestrator becomes the Don Juan after completing their quest, one Townsfolk might become an Outsider.","id":"donjuan_darkartists_stuff"},{"name":"Dreydra","align":"evil","text":"The Orchestrator-turned-Demon still registers as a Minion to the Dreydra.","id":"dreydra_darkartists_stuff"},{"name":"Faurein","align":"evil","text":"The Orchestrator-turned-Demon still registers as a Minion to the Faurein. The Orchestrator cannot be the Faurein.","id":"faurein_darkartists_stuff"},{"name":"Plea","align":"evil","text":"When the Orchestrator becomes the Plea after completing their quest, one Townsfolk might become an Outsider.","id":"plea_darkartists_stuff"}],"customBoxes":[{"title":"Alternative JSON & How to Run","content":"If you feel like the Orchestrator should be a bit more quiet at the cost of some survival power on the evil team, use this JSON.\n\nDuring setup, write the quest on a piece of paper, or on a phone.\n\nDuring the first night, wake the Orchestrator. Show this quest, then put them to sleep.\n\nTrack the Orchestrator''s progress towards this quest. They may visit you to make guesses or your quest may wake them each night to choose a player. Regardless, as the Orchestrator makes progress, use their DO, RE, MI reminders if you need to.\n\nUpon completing their quest, the Orchestrator will still obtain a Demon''s ability to use, but they will not be a Demon, and thus not uphold the evil team''s win condition to see the Demon reach the final 2. However, the Orchestrator''s is not revealed to everyone upon doing this, and the player who learns about the Orchestrator''s quest does not learn what not-in-play Demon ability they get.\n\nOnce the Orchestrator has completed their quest in full, replace the Orchestrator token with a Demon token that already isn''t in-play and mark them with the **IS ORCHESTRATOR** reminder token, granting the Orchestrator''s that Demon''s ability. Do not announce this publicly.\n\nIf you are in an environment that allows you to private message people anonymously (such as online), immediately message the Orchestrator what Demon they are, and message a good player a slight portion of the Orchestrator''s quest.\n\nIf you are in an environment that doesn''t allow you to privately message people anonymously (such as real life), mark the new Demon with the FASOLLATIDO reminder. That night, wake the Orchestrator-turned-Demon. Show them the YOU ARE info token, then their new Demon character token, then put them to sleep. If the quest was written on a piece of paper, find a way to obscure, cover, or limit visibility of most of the quest''s text, or just write a slither of an existing part of it onto a new piece of paper. Wake a good player. Show them the remaining visible portion of the quest. Put the good player to sleep.\n\n**Orchestrator █~** (Minion)\nYou start with a quest. If completed, you gain a not-in-play Demon ability & 1 good player learns part of the quest.\n\n**First night:** Show the Orchestrator their quest.\n**Other nights:** If the Orchestrator has completed their quest: Wake them and show them the ''You are'' card and the relevant Demon character token. Wake 1 good player, show them the ''This character selected you'' card, show the Orchestrator token and show them a slight part of the quest.\n**Reminders:** Do, Re, Mi, Fasollatido, Is Orchestrator\n**Credit:** Ability: @legitch. Image: @quorglepleegjr\n\n**Jinxes:**\nFang Gu: When the Orchestrator becomes the Fang Gu after completing their quest, one Townsfolk might become an Outsider.\nKazali: When the Orchestrator becomes the Kazali after completing their quest, Minions & other Demons wake the same night to choose which Minion & Demon characters they''d like to be.\nLegion: When the Orchestrator becomes the Legion after completing their quest, one player becomes an evil Legion.\nLeviathan: When the Orchestrator becomes the Leviathan after completing their quest, if its after Day 5, there is 1 more day before evil wins.\nLil'' Monsta: The Orchestrator cannot become the Lil'' Monsta.\nRiot: The Orchestrator-turned-Riot''s ability cannot win the game, but is still active even if they die.\nVigormortis: The Orchestrator-turned-Demon still registers as a Minion to the Vigormortis.\n▼: When a Orchestrator becomes the ∇ after completing their quest, any Minions & Demons might become ones from the Trouble Brewing set.\nCespholopod: The Orchestrator cannot become the Cespholopod.\nEyeceue: The Orchestrator cannot become the Eyeceue.\nHaedlaite: When the Orchestrator becomes the Haedlaite after completing their quest, one Minion becomes a Haedlaite but still registers as a Minion.\nLettucbaken: When the Orchestrator becomes the Lettucbaken after completing their quest, only the good player learning part of the quest learns this & the original Demon loses their ability.\nPecks: When the Orchestrator becomes the Pecks after completing their quest, all other evil players become a Pecks, then revert back to their previous character once the original Pecks dies.\nWatislujv: A Orchestrator-turned-Watislujv will register any Minion as a good Minion.\nxX_2662_Xx: When the Orchestrator becomes the xX_2662_Xx after completing their quest, all players are instead alerted to the presence of the 2nd Demon ability they have.\nAu’Wre: The Orchestrator cannot become the Au''Wre\nCawthane: If the Orchestrator would''ve become a Cawthane, instead, they get to choose which player to make an evil Cawthane.\nFencer: The Fencer only learns of original Demon''s choices.\nKetos: When the Orchestrator become the Ketos after completing their quest, if its after Day 5, there is 1 more day before evil wins.\nTiresias: The Orchestrator-turned-Demon still registers as a Minion to the Seer. The Orchestrator cannot become the Seer.\nQiong Qi: When the Orchestrator becomes the Qiong Qi after completing their quest, one Townsfolk might become an Outsider.\nTao Tie: When the Orchestrator becomes the Taotie after completing their quest, one Townsfolk might become an Outsider.\nTao Wu: The Orchestrator-turned-Demon still registers as a Minion to the Tao Wu.\nCacophony: When the Orchestrator becomes the Cacophony after completing their quest, one Townsfolk might become an Outsider.\nFawn: The Orchestrator-turned-Demon still registers as a Minion to the Fawn.\nOlalla: When the Orchestrator becomes the Olalla after completing their quest, one Townsfolk might become an Outsider.\nCataphractos: The Orchestrator-turned-Demon still registers as a Minion to the Cataphractos.\nSwitchblame: When the Orchestrator becomes the Switchblame after completing their quest, if its after Day 4, there is 1 more day before evil wins.\nAunemoia: When the Orchestrator becomes the Aunemoia after completing their quest, one Townsfolk might become an Outsider.\nBadoch: The Orchestrator cannot become the Badoch.\nDaivout: When the Orchestrator would become the Daivout after completing their quest, instead, something very bad happens to the good team.\nDon Juan: When the Orchestrator becomes the Don Juan after completing their quest, one Townsfolk might become an Outsider.\nDreydra: The Orchestrator-turned-Demon still registers as a Minion to the Dreydra.\nFaurein: The Orchestrator-turned-Demon still registers as a Minion to the Faurein. The Orchestrator cannot be the Faurein.\nPlea: When the Orchestrator becomes the Plea after completing their quest, one Townsfolk might become an Outsider."}],"firstNight":12.012,"otherNight":27.012,"reminders":["Do","Re","Mi","Fasollatido"],"setup":false,"firstNightReminder":"Show the Orchestrator their quest.","otherNightReminder":"If the Orchestrator has completed their quest: Wake them and show them the ''You are'' card and the relevant Demon character token. Wake 1 good player, show them the ''This character selected you'' card, show the Orchestrator token and show them a slight part of the quest.","art":"art/orchestrator.png","jsonId":"orchestrator_scp_fragmented_veil","curata":false}','scp-fragmented-veil/orchestrator','published',datetime('now'),datetime('now'));
